function greeting_shortcode( $atts ) {
    $atts = shortcode_atts( array( 'name' => 'World' ), $atts, 'greeting' );
    return 'Hello, ' . esc_html( $atts['name'] ) . '!';
}
add_shortcode( 'greeting', 'greeting_shortcode' );

